const aNav=document.getElementById('navMenuAdminAnnouncements');const spanPage=document.createElement('span');spanPage.innerHTML=aNav.innerHTML;spanPage.className=aNav.className+' active';spanPage.id=aNav.id;spanPage.setAttribute('aria-current','page');aNav.replaceWith(spanPage);limitAnnouncementCheck();let tableConfig={colIndices:{name:null,title:0,description:1,date:2,},hasNameSearch:!1,};let announcement=null;document.getElementById("editDialog").addEventListener("click",function(e){if(e.target===this){closeEditDialog()}});document.addEventListener("keydown",function(e){if(e.key==="Escape"){closeEditDialog()}});document.getElementById("dialogDelete").addEventListener("click",function(e){if(e.target===this){closeDeleteDialog()}});document.addEventListener("keydown",function(e){if(e.key==="Escape"){closeDeleteDialog()}});const form=document.getElementById("editAnnouncementForm");form.onsubmit=function(event){event.preventDefault();const data=new FormData(event.target);const title=data.get("title");const description=data.get("description");editAnnouncement(title,description)};function limitAnnouncementCheck(){const tbody=document.getElementById('tableBody');let allRows=Array.from(tbody.querySelectorAll('tr'));if(allRows.length>=5){document.getElementById("editBtn").setAttribute('disabled','true')}}
function openDeleteDialog(id){announcement=id;document.getElementById("dialogDelete").classList.add("active");dialog=document.getElementById('dialogDelete')
dialog.focus()}
function closeDeleteDialog(){document.getElementById("dialogDelete").classList.remove("active");announcement=null}
function deleteAnnouncement(){fetch("../controller/deleteAnnouncementController.php",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded",},body:"idAnnuncio="+encodeURIComponent(announcement),}).then(()=>{location.reload()}).catch((error)=>{console.error("Error:",error)});closeDeleteDialog()}
function openEditDialog(id,button){const currentRow=button.closest("tr");const cells=currentRow.cells;const indices=tableConfig.colIndices;announcement=id;document.getElementById("editDialog").classList.add("active");dialog=document.getElementById("editDialog");dialog.focus();const title_edit=document.getElementById("title-edit");const description_edit=document.getElementById("description-edit");title_edit.value=cells[indices.title].textContent.trim();description_edit.value=cells[indices.description].textContent.trim()}
function closeEditDialog(){document.getElementById("editDialog").classList.remove("active");announcement=null}
function editAnnouncement(title,description){fetch("../controller/editAnnouncementController.php",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded",},body:"idAnnuncio="+encodeURIComponent(announcement)+"&title="+encodeURIComponent(title)+"&description="+encodeURIComponent(description),}).then(()=>{location.reload()}).catch((error)=>{console.error("Error:",error)});closeDeleteDialog()}